(() => {
  'use strict';
  const root=document.documentElement, reduced=matchMedia('(prefers-reduced-motion: reduce)'), motion=document.querySelector('.motion-toggle');
  root.classList.add('js-enabled'); let paused=reduced.matches;
  function setMotion(value){paused=value;root.classList.toggle('motion-paused',paused);root.classList.toggle('motion-allowed',!paused);if(motion){motion.setAttribute('aria-pressed',String(paused));motion.title=paused?'Resume website animations':'Pause website animations';motion.setAttribute('aria-label',`${paused?'Motion off':'Motion on'}. ${motion.title}`);motion.innerHTML=`<svg aria-hidden="true" width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="${paused?'M5 3l7 5-7 5z':'M5 3v10M11 3v10'}"></path></svg><span>Motion ${paused?'off':'on'}</span>`;}}
  setMotion(paused);motion?.addEventListener('click',()=>setMotion(!paused));reduced.addEventListener('change',e=>setMotion(e.matches));
  let scrollFrame=0;window.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;root.style.setProperty('--reading-progress',`${total>0?100*scrollY/total:0}%`);scrollFrame=0;});},{passive:true});
  if('IntersectionObserver' in window){root.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(n=>observer.observe(n));}
  const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
  function closeMenu(){nav?.classList.remove('is-open');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Open navigation');}
  menu?.addEventListener('click',()=>{const opened=nav.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(opened));menu.setAttribute('aria-label',opened?'Close navigation':'Open navigation');});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));matchMedia('(max-width:760px)').addEventListener('change',closeMenu);document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenu();});document.addEventListener('focusin',e=>{if(!e.target.closest('.site-header'))closeMenu();});document.querySelectorAll('a[href*="#"]').forEach(a=>a.addEventListener('click',()=>{const url=new URL(a.href,location.href);if(url.pathname!==location.pathname||!url.hash)return;const destination=document.getElementById(decodeURIComponent(url.hash.slice(1)));if(destination){destination.setAttribute('tabindex','-1');destination.focus({preventScroll:true});}}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('is-open')){closeMenu();menu.focus();}});
  const shots=document.querySelectorAll('[data-shot]');shots.forEach(b=>b.addEventListener('click',()=>{shots.forEach(s=>s.setAttribute('aria-pressed',String(s===b)));const image=document.querySelector('#workspace-shot');image.src=b.dataset.shot;image.alt=`Clipora native Windows app: ${b.textContent}. Synthetic content.`;document.querySelector('#shot-label').textContent=`Clipora · ${b.textContent}`;}));
  const search=document.querySelector('#clip-search');if(!search)return;
  const initial=[{id:'reply',type:'text',title:'A little thank-you',text:'Thanks for reaching out! I’ll take a look and get back to you shortly.',detail:'Text · Your go-to reply',pin:true},{id:'link',type:'link',title:'The link you were looking for',text:'https://clipora.deltabits.in/guide',detail:'Link · Clipora quick-start guide',pin:false},{id:'image',type:'image',title:'A workspace worth keeping',text:'[Sample image: Clipora workspace]',detail:'Image · Synthetic app screenshot',pin:false},{id:'idea',type:'text',title:'An idea for later',text:'Make the little things easier. Leave more room for the big ideas.',detail:'Text · A note to yourself',pin:false},{id:'meeting',type:'text',title:'The meeting follow-up',text:'Great speaking with you today. Here are the next steps we discussed.',detail:'Text · A reusable snippet',pin:false}];
  let clips=initial.map(c=>({...c})),filter='all',selected='reply';const list=document.querySelector('#clip-results'),status=document.querySelector('#demo-status'),target=document.querySelector('#paste-target'),clear=document.querySelector('#clear-search');
  function matches(){const q=search.value.trim().toLowerCase();return clips.filter(c=>(filter==='all'||c.type===filter)&&`${c.title} ${c.text} ${c.detail}`.toLowerCase().includes(q)).sort((a,b)=>Number(b.pin)-Number(a.pin));}
  function paste(c){const origin=list.querySelector(`[data-clip-id="${c.id}"] .clip-main`)?.getBoundingClientRect();target.setRangeText(c.text,target.selectionStart,target.selectionEnd,'end');target.focus();target.classList.remove('paste-flash');void target.offsetWidth;target.classList.add('paste-flash');status.textContent=c.type==='image'?'Image selected. A text placeholder was inserted in this demo.':'Sample pasted into the example field.';selected=c.id;render();animatePaste(origin);if(lesson&&copied&&c.id===lessons[lesson].target){setProgress('done');document.querySelector('#lesson-completion').textContent=lesson==='plain'?'Done. The words were pasted without rich formatting in this example.':'Done. An earlier copy is back where you need it.';}}
  function render(){const previousScroll=list.scrollTop;const visible=matches();if(!visible.some(c=>c.id===selected))selected=visible[0]?.id;list.replaceChildren();clear.hidden=!search.value;document.querySelector('#result-count').textContent=`${visible.length} ${visible.length===1?'clip':'clips'} · pins first`;if(!visible.length){const p=document.createElement('p');p.className='empty-results';p.textContent='Nothing here yet. Try another word or clear your search.';list.append(p);return;}visible.forEach(c=>{const row=document.createElement('div');row.className=`clip-row${selected===c.id?' is-selected':''}`;row.dataset.clipId=c.id;const main=document.createElement('button');main.className='clip-main';main.title=c.type==='image'?'Select sample image':'Paste sample';const icon=document.createElement('span');icon.className='clip-icon';icon.setAttribute('aria-hidden','true');if(c.type==='image'){const img=document.createElement('img');img.src='/library.png';img.alt='';img.width=36;img.height=30;icon.append(img);}else icon.textContent=c.type==='link'?'↗':'Aa';const copy=document.createElement('span'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=c.title;sub.textContent=(c.pin?'Pinned · ':'')+c.detail;copy.append(title,sub);main.append(icon,copy);main.addEventListener('click',()=>paste(c));const pin=document.createElement('button');pin.className='pin-button';pin.textContent=c.pin?'✦':'☆';pin.setAttribute('aria-pressed',String(c.pin));pin.setAttribute('aria-label',`${c.pin?'Unpin':'Pin'} ${c.title}`);pin.title=pin.getAttribute('aria-label');pin.addEventListener('click',()=>{c.pin=!c.pin;status.textContent=`${c.pin?'Pinned':'Unpinned'} ${c.title}.`;render();list.querySelector(`[data-clip-id="${c.id}"] .pin-button`)?.focus({preventScroll:true});});row.append(main,pin);list.append(row);});list.scrollTop=previousScroll;}
  function searchChanged(){render();if(lesson&&copied&&matches().some(c=>c.id===lessons[lesson].target))setProgress('paste');status.textContent=`${matches().length} sample clips found.`;}search.addEventListener('input',e=>{if(!e.isComposing)searchChanged();});search.addEventListener('compositionend',searchChanged);clear.addEventListener('click',()=>{search.value='';render();search.focus();status.textContent='Search cleared.';});search.addEventListener('keydown',e=>{if(e.isComposing)return;const items=matches(),at=items.findIndex(c=>c.id===selected);if((e.key==='ArrowDown'||e.key==='ArrowUp')&&items.length){e.preventDefault();const step=e.key==='ArrowDown'?1:-1;selected=items[(at+step+items.length)%items.length]?.id;render();list.querySelector('.is-selected')?.scrollIntoView({block:'nearest',behavior:'instant'});status.textContent=`Selected ${items.find(c=>c.id===selected).title}. Press Enter to paste.`;}if(e.key==='Enter'&&items.length){e.preventDefault();paste(items.find(c=>c.id===selected)||items[0]);}if(e.key==='Escape'){e.preventDefault();search.value='';render();status.textContent='Search cleared.';}});
  document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));render();status.textContent=`${matches().length} ${filter==='all'?'sample':filter} clips found.`;}));document.querySelectorAll('.segmented [data-theme]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#demo-picker').dataset.theme=b.dataset.theme;document.querySelectorAll('.segmented [data-theme]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));}));document.querySelectorAll('[data-density]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#demo-picker').classList.toggle('compact',b.dataset.density==='compact');document.querySelectorAll('[data-density]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));}));document.querySelector('#reset-demo').addEventListener('click',()=>{clips=initial.map(c=>({...c}));filter='all';selected='reply';search.value='';target.value='';document.querySelector('.segmented [data-theme="dark"]').click();document.querySelector('[data-density="roomy"]').click();list.scrollTop=0;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='all')));render();status.textContent='Demo reset. All sample clips are ready.';resetLesson();});render();
  const lessons={
    find:{target:'meeting',instruction:'Add a fresh copy, then find the older meeting follow-up. Search “meeting” and select the result.',sample:'Today’s launch checklist is ready.',preview:'Today’s launch checklist is ready.'},
    pin:{target:'reply',instruction:'Add a fresh copy. Your pinned thank-you stays at the top. Select it to reuse the reply.',sample:'A new copy arrives. Your favorite stays close.',preview:'A new copy arrives. Your favorite stays close.'},
    plain:{target:'lesson',instruction:'Add the styled sample, then select it. Its words arrive in the plain-text example field.',sample:'Weekly review\nBring your next useful idea.',preview:'<strong>Weekly review</strong><br><em>Bring your next useful idea.</em>'}
  };
  let lesson=null,copied=false;
  function setProgress(step){const order=['copy','find','paste'];document.querySelectorAll('.lesson-progress li').forEach(li=>{const i=order.indexOf(li.dataset.step),at=step==='done'?3:order.indexOf(step);li.classList.toggle('is-done',i<at);if(i===at)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});}
  function resetLesson(){lesson=null;copied=false;document.querySelector('.lesson-panel').hidden=true;document.querySelectorAll('[data-lesson]').forEach(b=>b.setAttribute('aria-pressed','false'));document.querySelector('#lesson-completion').textContent='';}
  document.querySelectorAll('[data-lesson]').forEach(button=>button.addEventListener('click',()=>{
    document.querySelector('#reset-demo').click();lesson=button.dataset.lesson;copied=false;button.setAttribute('aria-pressed','true');document.querySelector('.lesson-panel').hidden=false;
    document.querySelector('#lesson-instruction').textContent=lessons[lesson].instruction;
    document.querySelector('#lesson-preview').innerHTML=lessons[lesson].preview;
    document.querySelector('#lesson-copy').disabled=false;setProgress('copy');
  }));
  document.querySelector('#lesson-copy').addEventListener('click',()=>{
    if(!lesson||copied)return;copied=true;const l=lessons[lesson];clips.unshift({id:'lesson',type:'text',title:lesson==='plain'?'Weekly review':'Your newest copy',text:l.sample.replaceAll('\\n','\n'),detail:'Synthetic demo copy',pin:false});selected='lesson';render();setProgress('find');
    document.querySelector('#lesson-copy').disabled=true;document.querySelector('#lesson-completion').textContent='Sample added to demo history. Your device clipboard was not accessed.';status.textContent=lesson==='find'?'Now search for meeting.':lesson==='pin'?'Your pinned reply is still first.':'Select Weekly review to paste its words.';
  });
  function animatePaste(origin){
    if(!origin||root.classList.contains('motion-paused')||!Element.prototype.animate)return;
    const end=target.getBoundingClientRect(),chip=document.createElement('div');chip.className='transfer-chip';chip.textContent='Clip selected';chip.setAttribute('aria-hidden','true');chip.style.left=origin.left+'px';chip.style.top=origin.top+'px';document.body.append(chip);
    const animation=chip.animate([{transform:'translate(0,0) scale(.95)',opacity:0},{offset:.2,opacity:1},{transform:`translate(${end.left-origin.left+12}px,${end.top-origin.top+12}px) scale(.8)`,opacity:0}],{duration:480,easing:'cubic-bezier(.2,.7,.3,1)'});animation.finished.then(()=>chip.remove(),()=>chip.remove());
  }

})();
